FeatureSpec {
        id: Feature::BackendTools,
        key: "backend_tools",
        path: "features.backend_tools",
        // The variable predates the key and is not spelled after it.
        env: "GROK_BACKEND_SEARCH",
        default_enabled: true,
        remote: None,
    }

slash_meta! {
        name: "config-agents",
        aliases: ["agents"],
        description: "Manage agent definitions",
        usage: "/config-agents",
    }

slash_meta! {
        name: "dashboard",
        // `/sessions` stays as an alias after the sessions picker modal was removed, so old muscle memory redirects here
        // The dashboard replaced that modal for switching, renaming, and closing active sessions.
        // The aliases inherit the feature gate (`set_dashboard_visible` hides by canonical name) and the minimal-mode gate below
        aliases: ["agents-dashboard", "sessions"],
        description: "Open the Agent Dashboard",
        usage: "/dashboard",
        mode_support: ModeSupport::FullscreenOnly(Remedy::SwitchMode {
            why: "minimal is single-session",
        }),
    }

slash_meta! {
        name: "always-approve",
        description: "Toggle always-approve mode (skip all permission prompts)",
        usage: "/always-approve",
    }

slash_meta! {
        name: "auto",
        description: "Toggle auto mode (classifier approves safe tools)",
        usage: "/auto",
    }

slash_meta! {
        name: "cd",
        description: "Change the working directory for new agents",
        usage: "/cd [path]",
        takes_args: true,
        // `/cd` only makes sense on the dashboard (it changes where the dashboard dispatches new agents).
        // Hide it from completion everywhere else (the agent view and the welcome screen)
        dashboard_only: true,
        arg_placeholder: "path",
    }

